import click
import pytest
from click.testing import CliRunner

@pytest.fixture
def runner():
    return CliRunner()

def test_required_flag(runner):
    @click.command()
    @click.option("--flag", is_flag=True, required=True)
    def cli(flag):
        click.echo(flag)

    result = runner.invoke(cli, [])
    assert result.exit_code == 2
    assert "Error: Missing option '--flag'." in result.output

    result = runner.invoke(cli, ["--flag"])
    assert result.exit_code == 0
    assert result.output == "True\n"

def test_required_flag_with_default(runner):
    @click.command()
    @click.option("--flag", is_flag=True, required=True, default=True)
    def cli(flag):
        click.echo(flag)

    result = runner.invoke(cli, [])
    assert result.exit_code == 0
    assert result.output == "True\n"

def test_non_required_flag(runner):
    @click.command()
    @click.option("--flag", is_flag=True)
    def cli(flag):
        click.echo(flag)

    result = runner.invoke(cli, [])
    assert result.exit_code == 0
    assert result.output == "False\n"
EOF
